#[using="Type"] Lemma art_gfa_aruns :
  forall (Q : list aev -> machine_state -> Prop) (log : list aev) regs (M rom : word -> option byte) (raw : word)
         (sp HI t ctx tp key tsd spb ris qs c km m1 m2 sv : Z) (cl : art_cls),
